package com.shopstream.cart;

import java.time.Duration;
import java.util.Map;
import java.util.stream.Collectors;

import org.springframework.data.redis.core.HashOperations;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.stereotype.Service;

@Service
public class CartService {

    private static final Duration CART_TTL = Duration.ofDays(7);

    private final StringRedisTemplate redis;

    public CartService(StringRedisTemplate redis) {
        this.redis = redis;
    }

    private String key(long userId) {
        return "cart:" + userId;
    }

    public void addItem(long userId, String sku, int quantity) {
        HashOperations<String, String, String> ops = redis.opsForHash();
        ops.increment(key(userId), sku, quantity);
        redis.expire(key(userId), CART_TTL);
    }

    public Map<String, Integer> items(long userId) {
        HashOperations<String, String, String> ops = redis.opsForHash();
        return ops.entries(key(userId)).entrySet().stream()
                .collect(Collectors.toMap(Map.Entry::getKey,
                        e -> Integer.parseInt(e.getValue())));
    }
    public void clear(long userId) {
        redis.delete(key(userId));
    }
}
